using System.Reflection;
using System.Text.Json;
using System.Windows.Forms;
class Program {
 [STAThread] static void Main() {
  var asm=new[]{typeof(Control).Assembly,typeof(IWin32Window).Assembly}.Distinct();
  var controls=asm.SelectMany(a=>a.GetExportedTypes()).Where(t=>!t.IsAbstract&&!t.IsNested&&typeof(Control).IsAssignableFrom(t)).OrderBy(t=>t.FullName).Select(t=>new {Type=t.FullName,t.Name,Base=t.BaseType?.FullName,HasControlDoc=File.Exists("docs/roadmap/controls/"+t.Name+".md"),HasApiDoc=File.Exists("docs/roadmap/api/"+t.Name+".md")}).ToArray();
  var cases=new[]{typeof(BindingSource),typeof(BindingContext),typeof(TreeNodeCollection),typeof(ComboBox.ObjectCollection),typeof(ListView.ListViewItemCollection),typeof(IBindableComponent),typeof(DataObject)};
  var explicitCases=cases.Select(t=>new{Type=t.FullName,InheritedInterfaces=t.GetInterfaces().Select(x=>x.FullName),Explicit=t.IsInterface?[]:t.GetInterfaces().SelectMany(i=>{var map=t.GetInterfaceMap(i);return map.TargetMethods.Select((m,j)=>new{Interface=i.FullName,Member=map.InterfaceMethods[j].ToString(),Target=m.ToString(),Name=m.Name,m.IsPrivate,m.IsPublic});}).Where(x=>x.IsPrivate).ToArray(),DeclaredPublic=t.GetMembers(BindingFlags.DeclaredOnly|BindingFlags.Public|BindingFlags.Instance|BindingFlags.Static).Select(x=>x.Name).Distinct().ToArray()});
  var contracts=typeof(Control).GetInterfaces().Select(i=>new{i.FullName,i.IsVisible,i.IsPublic}).ToArray();
  string dotnetRoot=Directory.GetParent(System.Runtime.InteropServices.RuntimeEnvironment.GetRuntimeDirectory().TrimEnd(Path.DirectorySeparatorChar))!.Parent!.Parent!.FullName;
  string desktop=Path.Combine(dotnetRoot,"packs/Microsoft.WindowsDesktop.App.Ref/10.0.11/ref/net10.0"), core=Path.Combine(dotnetRoot,"packs/Microsoft.NETCore.App.Ref/10.0.11/ref/net10.0");
  using var mlc=new MetadataLoadContext(new PathAssemblyResolver(Directory.GetFiles(desktop,"*.dll").Concat(Directory.GetFiles(core,"*.dll"))),"System.Runtime");
  var refForms=mlc.LoadFromAssemblyPath(Path.Combine(desktop,"System.Windows.Forms.dll"));
  var refControl=refForms.GetType("System.Windows.Forms.Control")!;
  var refControls=refForms.GetExportedTypes().Where(t=>!t.IsAbstract&&!t.IsNested&&refControl.IsAssignableFrom(t)).OrderBy(t=>t.FullName).Select(t=>t.FullName).ToArray();
  string imageInsertRule;
  using(var images=new ImageList())using(var image=new System.Drawing.Bitmap(16,16)){try{((System.Collections.IList)images.Images).Insert(0,image);imageInsertRule="succeeded";}catch(Exception ex){imageInsertRule=ex.GetType().Name;}}
  var legacy=new[]{"Menu","MainMenu","ContextMenu","MenuItem","DataGrid","DataGridTextBox","DataGridBoolColumn","DataGridTextBoxColumn","DataGridTableStyle","ToolBar","StatusBar","ToolBarButton","StatusBarPanel"}.Select(n=>{var ty=typeof(Control).Assembly.GetType("System.Windows.Forms."+n)!;object? instance=null;string result;try{if(ty.IsAbstract)result="abstract";else{instance=Activator.CreateInstance(ty);result="constructed";}}catch(Exception ex){result=(ex is TargetInvocationException te?te.InnerException:ex)?.GetType().Name+": "+(ex is TargetInvocationException te2?te2.InnerException:ex)?.Message;}finally{(instance as IDisposable)?.Dispose();}return new{Type=ty.FullName,Obsolete=ty.GetCustomAttribute<ObsoleteAttribute>()?.Message,ObsoleteError=ty.GetCustomAttribute<ObsoleteAttribute>()?.IsError,Construction=result};});
  Console.WriteLine(JsonSerializer.Serialize(new{Count=controls.Length,ReferenceCount=refControls.Length,ReferenceControls=refControls,Controls=controls,ExplicitCases=explicitCases,ControlContracts=contracts,ImageInsertRule=imageInsertRule,Legacy=legacy},new JsonSerializerOptions{WriteIndented=true}));
 }
}
